use vstd::prelude::*;

verus! {

/// A Laguerre series, defined by its floating‐point coefficients
/// and two intervals (domain and window), here both fixed to [0.0, 1.0].
struct Laguerre {
    coefficients: Vec<f32>,
    domain: (f32, f32),
    window: (f32, f32),
}

/// Construct a Laguerre series from a given list of f32 coefficients.
/// The coefficients are stored exactly as given (same order and values),
/// and both the domain and window are set to the unit interval [0.0, 1.0].
fn make_laguerre(coefficients: Vec<f32>) -> (lag: Laguerre)
    ensures
        // The output coefficients sequence is identical to the input sequence
        lag.coefficients@ == coefficients@,
        // Domain and window are both set to [0.0, 1.0]
        lag.domain == (0.0_f32, 1.0_f32),
        lag.window == (0.0_f32, 1.0_f32),
{
    Laguerre {
        coefficients,
        domain: (0.0, 1.0),
        window: (0.0, 1.0),
    }
}

} // verus!

